const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const exe = b.addExecutable(.{
        .name = "underdog-llm",
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    exe.linkLibC();
    exe.linkSystemLibrary("cuda");
    exe.linkSystemLibrary("cudart");
    exe.linkSystemLibrary("cublas");
    exe.linkSystemLibrary("nccl");

    b.installArtifact(exe);

    const run_cmd = b.addRunArtifact(exe);
    if (b.args) |args| run_cmd.addArgs(args);

    const run_step = b.step("run", "Run underdog-llm");
    run_step.dependOn(&run_cmd.step);
}

import os
import subprocess
import sys

ROOT = os.path.dirname(os.path.abspath(__file__))


def run(cmd, cwd=ROOT):
    p = subprocess.run(cmd, cwd=cwd)
    if p.returncode != 0:
        raise SystemExit(p.returncode)


def main():
    optimize = os.environ.get("ZIG_OPT", "ReleaseFast")
    args = sys.argv[1:]
    run(["zig", "build", f"-Doptimize={optimize}"])
    if args:
        run(["zig", "build", "run", f"-Doptimize={optimize}", "--"] + args)


if __name__ == "__main__":
    main()

const std = @import("std");
const config_mod = @import("config.zig");
const mem = @import("memory.zig");
const nccl = @import("nccl.zig");
const efla = @import("train/efla.zig");
const lion = @import("train/optimizer/lion.zig");
const muon = @import("train/optimizer/muon.zig");

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var cfg = config_mod.TrainingConfig{};

    var args = std.process.args();
    _ = args.next();
    while (args.next()) |a| {
        if (std.mem.eql(u8, a, "--gpus")) {
            if (args.next()) |v| cfg.num_gpus = try std.fmt.parseInt(u32, v, 10);
        } else if (std.mem.eql(u8, a, "--steps")) {
            if (args.next()) |v| cfg.max_steps = try std.fmt.parseInt(u32, v, 10);
        } else if (std.mem.eql(u8, a, "--chunk")) {
            if (args.next()) |v| cfg.chunk_size = try std.fmt.parseInt(u32, v, 10);
        } else if (std.mem.eql(u8, a, "--dim")) {
            if (args.next()) |v| cfg.model_dim = try std.fmt.parseInt(u32, v, 10);
        } else if (std.mem.eql(u8, a, "--heads")) {
            if (args.next()) |v| cfg.num_heads = try std.fmt.parseInt(u32, v, 10);
        } else if (std.mem.eql(u8, a, "--layers")) {
            if (args.next()) |v| cfg.num_layers = try std.fmt.parseInt(u32, v, 10);
        } else if (std.mem.eql(u8, a, "--vocab")) {
            if (args.next()) |v| cfg.vocab_size = try std.fmt.parseInt(u32, v, 10);
        } else if (std.mem.eql(u8, a, "--lr")) {
            if (args.next()) |v| cfg.learning_rate = try std.fmt.parseFloat(f32, v);
        }
    }

    try cfg.validate();

    var mm = try mem.MemoryManager.init(allocator, cfg.num_gpus);
    defer mm.deinit();

    var comms = try nccl.NcclManager.init(allocator, cfg.num_gpus);
    defer comms.deinit();

    var model = try efla.EFLAModel.init(allocator, &mm, &comms, cfg);
    defer model.deinit();

    var muons = try allocator.alloc(muon.MuonOptimizer, cfg.num_gpus);
    var lions = try allocator.alloc(lion.LionOptimizer, cfg.num_gpus);
    defer {
        for (0..cfg.num_gpus) |i| {
            muons[i].deinit(&mm);
            lions[i].deinit(&mm);
        }
        allocator.free(muons);
        allocator.free(lions);
    }

    for (0..cfg.num_gpus) |i| {
        muons[i] = try muon.MuonOptimizer.init(allocator, &mm, model.get2DParams(@intCast(i)), .{ .lr = cfg.learning_rate, .weight_decay = cfg.weight_decay });
        lions[i] = try lion.LionOptimizer.init(allocator, &mm, model.get1DParams(@intCast(i)), .{ .lr = cfg.learning_rate, .weight_decay = cfg.weight_decay });
    }

    var prng = std.rand.DefaultPrng.init(0xdeadbeef);
    const rnd = prng.random();

    const seq_len: usize = cfg.chunk_size;
    var tokens = try allocator.alloc(u32, seq_len);
    defer allocator.free(tokens);

    var stdout = std.io.getStdOut().writer();

    for (0..cfg.max_steps) |step| {
        var loss_sum: f32 = 0;

        for (0..cfg.num_gpus) |gpu| {
            for (0..seq_len) |i| tokens[i] = rnd.intRangeLessThan(u32, 0, cfg.vocab_size);
            try model.zeroGrads(@intCast(gpu));
            const loss = try model.forwardBackwardChunk(@intCast(gpu), tokens);
            loss_sum += loss;
        }

        for (0..cfg.num_gpus) |gpu| {
            try model.clipAndAllReduce(@intCast(gpu));
        }

        for (0..cfg.num_gpus) |gpu| {
            muons[gpu].step(model.get2DParams(@intCast(gpu)), model.get2DGrads(@intCast(gpu)));
            lions[gpu].step(model.get1DParams(@intCast(gpu)), model.get1DGrads(@intCast(gpu)));
        }

        if (@as(u32, @intCast(step)) % cfg.log_interval == 0) {
            const avg_loss = loss_sum / @as(f32, @floatFromInt(cfg.num_gpus));
            try stdout.print("step {d} loss {d:.6}\n", .{ step, avg_loss });
        }
    }
}

const mem = @import("memory.zig");

pub const TrainingConfig = struct {
    num_gpus: u32 = 1,
    model_dim: u32 = 4096,
    num_heads: u32 = 32,
    num_layers: u32 = 32,
    vocab_size: u32 = 50257,
    chunk_size: u32 = 1024,
    batch_size: u32 = 1,
    learning_rate: f32 = 1e-4,
    weight_decay: f32 = 0.01,
    precision: mem.Precision = .fp32,
    grad_precision: mem.Precision = .fp32,
    optimizer_precision: mem.Precision = .fp32,
    eps: f32 = 1e-5,
    gradient_clip_norm: f32 = 1.0,
    warmup_steps: u32 = 100,
    max_steps: u32 = 1000,
    log_interval: u32 = 10,
    activation_checkpoint_interval: u32 = 1,

    pub fn validate(self: TrainingConfig) !void {
        if (self.num_gpus == 0) return error.InvalidConfig;
        if (self.model_dim == 0) return error.InvalidConfig;
        if (self.num_heads == 0) return error.InvalidConfig;
        if (self.model_dim % self.num_heads != 0) return error.InvalidConfig;
        if (self.num_layers == 0) return error.InvalidConfig;
        if (self.vocab_size == 0) return error.InvalidConfig;
        if (self.chunk_size == 0) return error.InvalidConfig;
        if (self.batch_size == 0) return error.InvalidConfig;
        if (self.learning_rate <= 0) return error.InvalidConfig;
        if (self.gradient_clip_norm <= 0) return error.InvalidConfig;
        if (self.activation_checkpoint_interval == 0) return error.InvalidConfig;
    }
};

const std = @import("std");

const c = @cImport({
    @cInclude("cuda_runtime_api.h");
});

pub const Precision = enum {
    fp32,
    fp16,
    bf16,
    mxfp8,
    int8,
};

pub fn precisionBytes(p: Precision) usize {
    return switch (p) {
        .fp32 => 4,
        .fp16 => 2,
        .bf16 => 2,
        .mxfp8 => 1,
        .int8 => 1,
    };
}

pub const MemoryLocation = enum {
    host,
    pinned,
    gpu,
};

pub const MemoryError = error{
    CudaError,
    OutOfMemory,
    InvalidArgument,
};

pub fn cudaCheck(status: c.cudaError_t) MemoryError!void {
    if (status == c.cudaSuccess) return;
    if (status == c.cudaErrorMemoryAllocation) return error.OutOfMemory;
    if (status == c.cudaErrorInvalidValue) return error.InvalidArgument;
    return error.CudaError;
}

pub const MemoryBlock = struct {
    ptr: ?*anyopaque,
    size_bytes: usize,
    location: MemoryLocation,
    device_id: u32,

    pub fn slice(self: MemoryBlock, comptime T: type) []T {
        const p = @as([*]T, @ptrCast(@alignCast(self.ptr.?)));
        return p[0 .. self.size_bytes / @sizeOf(T)];
    }

    pub fn devicePtr(self: MemoryBlock) *anyopaque {
        return self.ptr.?;
    }
};

pub const MemoryManager = struct {
    allocator: std.mem.Allocator,
    num_gpus: u32,

    pub fn init(allocator: std.mem.Allocator, num_gpus: u32) !MemoryManager {
        if (num_gpus == 0) return error.InvalidArgument;
        return .{ .allocator = allocator, .num_gpus = num_gpus };
    }

    pub fn deinit(self: *MemoryManager) void {
        _ = self;
    }

    pub fn allocGPU(self: *MemoryManager, size_bytes: usize, device_id: u32) !MemoryBlock {
        _ = self;
        if (device_id >= self.num_gpus) return error.InvalidArgument;
        try cudaCheck(c.cudaSetDevice(@intCast(device_id)));
        var p: ?*anyopaque = null;
        const st = c.cudaMalloc(&p, size_bytes);
        try cudaCheck(st);
        return .{ .ptr = p, .size_bytes = size_bytes, .location = .gpu, .device_id = device_id };
    }

    pub fn freeGPU(self: *MemoryManager, block: *MemoryBlock) void {
        _ = self;
        if (block.location != .gpu) return;
        if (block.ptr) |p| {
            _ = c.cudaSetDevice(@intCast(block.device_id));
            _ = c.cudaFree(p);
        }
        block.* = .{ .ptr = null, .size_bytes = 0, .location = .gpu, .device_id = block.device_id };
    }

    pub fn allocPinned(self: *MemoryManager, size_bytes: usize) !MemoryBlock {
        _ = self;
        var p: ?*anyopaque = null;
        const st = c.cudaMallocHost(&p, size_bytes);
        try cudaCheck(st);
        return .{ .ptr = p, .size_bytes = size_bytes, .location = .pinned, .device_id = 0 };
    }

    pub fn freePinned(self: *MemoryManager, block: *MemoryBlock) void {
        _ = self;
        if (block.location != .pinned) return;
        if (block.ptr) |p| {
            _ = c.cudaFreeHost(p);
        }
        block.* = .{ .ptr = null, .size_bytes = 0, .location = .pinned, .device_id = 0 };
    }

    pub fn memcpyHtoD(self: *MemoryManager, dst: MemoryBlock, src: MemoryBlock) !void {
        _ = self;
        if (dst.location != .gpu) return error.InvalidArgument;
        if (src.location == .gpu) return error.InvalidArgument;
        if (dst.size_bytes != src.size_bytes) return error.InvalidArgument;
        try cudaCheck(c.cudaSetDevice(@intCast(dst.device_id)));
        try cudaCheck(c.cudaMemcpy(dst.ptr.?, src.ptr.?, dst.size_bytes, c.cudaMemcpyHostToDevice));
    }

    pub fn memcpyDtoH(self: *MemoryManager, dst: MemoryBlock, src: MemoryBlock) !void {
        _ = self;
        if (src.location != .gpu) return error.InvalidArgument;
        if (dst.location == .gpu) return error.InvalidArgument;
        if (dst.size_bytes != src.size_bytes) return error.InvalidArgument;
        try cudaCheck(c.cudaSetDevice(@intCast(src.device_id)));
        try cudaCheck(c.cudaMemcpy(dst.ptr.?, src.ptr.?, src.size_bytes, c.cudaMemcpyDeviceToHost));
    }

    pub fn memcpyDtoD(self: *MemoryManager, dst: MemoryBlock, src: MemoryBlock) !void {
        _ = self;
        if (dst.location != .gpu or src.location != .gpu) return error.InvalidArgument;
        if (dst.size_bytes != src.size_bytes) return error.InvalidArgument;
        try cudaCheck(c.cudaSetDevice(@intCast(dst.device_id)));
        try cudaCheck(c.cudaMemcpy(dst.ptr.?, src.ptr.?, dst.size_bytes, c.cudaMemcpyDeviceToDevice));
    }
};

pub const TensorDescriptor = struct {
    data: *anyopaque,
    size_bytes: usize,
    device_id: u32,
    num_elements: usize,
};

const std = @import("std");

const c = @cImport({
    @cInclude("nccl.h");
    @cInclude("cuda_runtime_api.h");
});

pub const NcclError = error{
    NcclError,
    InvalidArgument,
};

fn ncclCheck(res: c.ncclResult_t) NcclError!void {
    if (res == c.ncclSuccess) return;
    return error.NcclError;
}

pub const NcclComm = struct {
    comm: c.ncclComm_t,
    rank: u32,
    nranks: u32,
    device_id: u32,
};

pub const NcclManager = struct {
    allocator: std.mem.Allocator,
    comms: []NcclComm,

    pub fn init(allocator: std.mem.Allocator, num_gpus: u32) !NcclManager {
        if (num_gpus == 0) return error.InvalidArgument;
        var comms = try allocator.alloc(NcclComm, num_gpus);
        errdefer allocator.free(comms);

        var raw = try allocator.alloc(c.ncclComm_t, num_gpus);
        defer allocator.free(raw);

        var devs = try allocator.alloc(c_int, num_gpus);
        defer allocator.free(devs);
        for (devs, 0..) |*d, i| d.* = @intCast(i);

        try ncclCheck(c.ncclCommInitAll(raw.ptr, @intCast(num_gpus), devs.ptr));

        for (comms, 0..) |*cc, i| {
            cc.* = .{ .comm = raw[i], .rank = @intCast(i), .nranks = num_gpus, .device_id = @intCast(i) };
        }

        return .{ .allocator = allocator, .comms = comms };
    }

    pub fn deinit(self: *NcclManager) void {
        for (self.comms) |cc| {
            _ = c.ncclCommDestroy(cc.comm);
        }
        self.allocator.free(self.comms);
    }

    pub fn allReduceF32(self: *NcclManager, device_id: u32, buf: *anyopaque, count: usize, stream: c.cudaStream_t) !void {
        if (device_id >= self.comms.len) return error.InvalidArgument;
        const cc = self.comms[device_id];
        try ncclCheck(c.ncclAllReduce(buf, buf, @intCast(count), c.ncclFloat, c.ncclSum, cc.comm, stream));
    }
};

const std = @import("std");

pub const NVMeError = error{
    IoError,
    InvalidArgument,
};

pub const NVMeManager = struct {
    allocator: std.mem.Allocator,
    base_path: []const u8,

    pub fn init(allocator: std.mem.Allocator, base_path: []const u8) !NVMeManager {
        if (base_path.len == 0) return error.InvalidArgument;
        return .{ .allocator = allocator, .base_path = try allocator.dupe(u8, base_path) };
    }

    pub fn deinit(self: *NVMeManager) void {
        self.allocator.free(self.base_path);
    }

    fn makePath(self: *NVMeManager, name: []const u8) ![]u8 {
        return std.fmt.allocPrint(self.allocator, "{s}/{s}", .{ self.base_path, name });
    }

    pub fn writeAll(self: *NVMeManager, name: []const u8, data: []const u8) !void {
        const path = try self.makePath(name);
        defer self.allocator.free(path);
        var file = std.fs.cwd().createFile(path, .{ .truncate = true }) catch return error.IoError;
        defer file.close();
        file.writeAll(data) catch return error.IoError;
    }

    pub fn readAll(self: *NVMeManager, name: []const u8, dst: []u8) !void {
        const path = try self.makePath(name);
        defer self.allocator.free(path);
        var file = std.fs.cwd().openFile(path, .{}) catch return error.IoError;
        defer file.close();
        const n = file.readAll(dst) catch return error.IoError;
        if (n != dst.len) return error.IoError;
    }
};

