extern fn launchLionStep(params: *f32, m: *f32, grads: *const f32, lr: f32, beta1: f32, beta2: f32, weight_decay: f32, num_elements: usize, device_id: u32) void;

pub const LionConfig = struct {
    lr: f32,
    beta1: f32 = 0.9,
    beta2: f32 = 0.99,
    weight_decay: f32,
};

pub const LionOptimizer = struct {
    allocator: std.mem.Allocator,
    cfg: LionConfig,
    momentums: []mem.MemoryBlock,

    pub fn init(allocator: std.mem.Allocator, mm: *mem.MemoryManager, params: []const mem.TensorDescriptor, cfg: LionConfig) !LionOptimizer {
        var moms = try allocator.alloc(mem.MemoryBlock, params.len);
        errdefer allocator.free(moms);
        for (params, 0..) |p, i| {
            moms[i] = try mm.allocGPU(p.num_elements * @sizeOf(f32), p.device_id);
        }
        return .{ .allocator = allocator, .cfg = cfg, .momentums = moms };
    }

    pub fn deinit(self: *LionOptimizer, mm: *mem.MemoryManager) void {
        for (self.momentums) |*m| mm.freeGPU(m);
        self.allocator.free(self.momentums);
    }

    pub fn step(self: *LionOptimizer, params: []const mem.TensorDescriptor, grads: []const mem.TensorDescriptor) void {
        for (params, 0..) |p, i| {
            const g = grads[i];
            const m = self.momentums[i];
            launchLionStep(@as(*f32, @ptrCast(@alignCast(p.data))), @as(*f32, @ptrCast(@alignCast(m.ptr.?))), @as(*const f32, @ptrCast(@alignCast(g.data))), self.cfg.lr, self.cfg.beta1, self.cfg.beta2, self.cfg.weight_decay, p.num_elements, p.device_id);
        }
    }
};

