const std = @import("std");

pub const LossScaler = struct {
    scale: f32,
    growth_factor: f32,
    backoff_factor: f32,
    growth_interval: u32,
    growth_tracker: u32,

    pub fn init(init_scale: f32, growth_factor: f32, backoff_factor: f32, growth_interval: u32) LossScaler {
        return .{ .scale = init_scale, .growth_factor = growth_factor, .backoff_factor = backoff_factor, .growth_interval = growth_interval, .growth_tracker = 0 };
    }

    pub fn update(self: *LossScaler, overflow: bool) void {
        if (overflow) {
            self.scale *= self.backoff_factor;
            if (self.scale < 1) self.scale = 1;
            self.growth_tracker = 0;
        } else {
            self.growth_tracker += 1;
            if (self.growth_tracker >= self.growth_interval) {
                self.scale *= self.growth_factor;
                self.growth_tracker = 0;
            }
        }
    }
};

let f32_eps = 1e-8f32

let rms_norm [n] (x: [n]f32) (scale: [n]f32) (bias: [n]f32) (eps: f32) : [n]f32 =
  let mean_sq = (reduce (+) 0f32 (map (\v -> v*v) x)) / f32.i32 n
  let inv = 1f32 / f32.sqrt (mean_sq + eps)
  map3 (\v s b -> v*inv*s + b) x scale bias

let matmul_2d [m][k][n] (a: [m][k]f32) (b: [k][n]f32) : [m][n]f32 =
  map (\row ->
    map (\j ->
      reduce (+) 0f32 (map2 (\x y -> x*y) row (map (\r -> r[j]) b)))
    (iota n))
  a

let matvec [m][n] (a: [m][n]f32) (x: [n]f32) : [m]f32 =
  map (\row -> reduce (+) 0f32 (map2 (\u v -> u*v) row x)) a

let outer [m][n] (u: [m]f32) (v: [n]f32) : [m][n]f32 =
  map (\ui -> map (\vj -> ui*vj) v) u

let efla_head_step [d] (decay: f32) (k_mem: [d][d]f32) (v_mem: [d][d]f32) (q: [d]f32) (k: [d]f32) (v: [d]f32) : ([d][d]f32, [d][d]f32, [d]f32) =
  let k_mem' = map (\row -> map (\x -> x*decay) row) k_mem
  let v_mem' = map (\row -> map (\x -> x*decay) row) v_mem
  let k_mem'' = map2 (\r1 r2 -> map2 (+) r1 r2) k_mem' (outer k k)
  let v_mem'' = map2 (\r1 r2 -> map2 (+) r1 r2) v_mem' (outer v k)
  let denom_vec = matvec k_mem'' q
  let denom = f32_eps + reduce (+) 0f32 (map f32.abs denom_vec)
  let out = map (\x -> x/denom) (matvec v_mem'' q)
  in (k_mem'', v_mem'', out)

let split_qkv [seq][d_model] (qkv: [seq][3*d_model]f32) : ([seq][d_model]f32, [seq][d_model]f32, [seq][d_model]f32) =
  let q = map (\row -> row[0:d_model]) qkv
  let k = map (\row -> row[d_model:2*d_model]) qkv
  let v = map (\row -> row[2*d_model:3*d_model]) qkv
  in (q,k,v)

let reshape_qkv [seq][d_model][num_heads] (x: [seq][d_model]f32) : [seq][num_heads][d_model/num_heads]f32 =
  let head_dim = d_model / num_heads
  map (\row ->
    map (\h -> row[h*head_dim:(h+1)*head_dim]) (iota num_heads))
  x

let concat_heads [seq][num_heads][head_dim] (x: [seq][num_heads][head_dim]f32) : [seq][num_heads*head_dim]f32 =
  map (\tok ->
    concat tok)
  x

let efla_forward_chunk [seq][d_model][num_heads]
  (hidden: [seq][d_model]f32)
  (qkv_weight: [d_model][3*d_model]f32)
  (fw_key_init: [num_heads][d_model/num_heads][d_model/num_heads]f32)
  (fw_val_init: [num_heads][d_model/num_heads][d_model/num_heads]f32)
  (decay: [num_heads]f32)
  (out_weight: [d_model][d_model]f32)
  (norm_scale: [d_model]f32)
  (norm_bias: [d_model]f32)
  (eps: f32)
  : [seq][d_model]f32 =
  let h_norm = map (\row -> rms_norm row norm_scale norm_bias eps) hidden
  let qkv = matmul_2d h_norm qkv_weight
  let (q0,k0,v0) = split_qkv qkv
  let q = reshape_qkv q0
  let k = reshape_qkv k0
  let v = reshape_qkv v0
  let head_dim = d_model / num_heads
  let init_states = zip fw_key_init fw_val_init
  let step (states: [num_heads]([head_dim][head_dim]f32,[head_dim][head_dim]f32)) (t: i32)
      : ([num_heads]([head_dim][head_dim]f32,[head_dim][head_dim]f32), [num_heads][head_dim]f32) =
        let outs = map3 (\st h ->
          let (km,vm) = st
          let (km2,vm2,o) = efla_head_step decay[h] km vm q[t,h,:] k[t,h,:] v[t,h,:]
          in ((km2,vm2), o))
          states (iota num_heads)
        let new_states = map (\x -> x.0) outs
        let out_tok = map (\x -> x.1) outs
        in (new_states, out_tok)
  let scan_res = loop (states, acc) = (init_states, replicate seq (replicate num_heads (replicate head_dim 0f32))) for t in iota seq do
    let (states2, out_tok) = step states t
    in (states2, acc with [t] = out_tok)
  let head_out = scan_res.1
  let concat_out = concat_heads head_out
  let proj = matmul_2d concat_out out_weight
  map2 (\a b -> map2 (+) a b) hidden proj

entry efla_forward_entry [seq][d_model][num_heads]
  (hidden: [seq][d_model]f32)
  (qkv_weight: [d_model][3*d_model]f32)
  (fw_key_init: [num_heads][d_model/num_heads][d_model/num_heads]f32)
  (fw_val_init: [num_heads][d_model/num_heads][d_model/num_heads]f32)
  (decay: [num_heads]f32)
  (out_weight: [d_model][d_model]f32)
  (norm_scale: [d_model]f32)
  (norm_bias: [d_model]f32)
  (eps: f32) =
  efla_forward_chunk hidden qkv_weight fw_key_init fw_val_init decay out_weight norm_scale norm_bias eps

entry efla_backward_chunk [seq][d_model][num_heads]
  (hidden: [seq][d_model]f32)
  (qkv_weight: [d_model][3*d_model]f32)
  (fw_key_init: [num_heads][d_model/num_heads][d_model/num_heads]f32)
  (fw_val_init: [num_heads][d_model/num_heads][d_model/num_heads]f32)
  (decay: [num_heads]f32)
  (out_weight: [d_model][d_model]f32)
  (norm_scale: [d_model]f32)
  (norm_bias: [d_model]f32)
  (eps: f32)
  (grad_out: [seq][d_model]f32)
  : ([seq][d_model]f32,
     [d_model][3*d_model]f32,
     [num_heads][d_model/num_heads][d_model/num_heads]f32,
     [num_heads][d_model/num_heads][d_model/num_heads]f32,
     [num_heads]f32,
     [d_model][d_model]f32,
     [d_model]f32,
     [d_model]f32) =
  vjp (\(h, wqkv, fk, fv, d, wo, ns, nb) -> efla_forward_chunk h wqkv fk fv d wo ns nb eps)
      (hidden, qkv_weight, fw_key_init, fw_val_init, decay, out_weight, norm_scale, norm_bias)
      grad_out

let silu (x: f32) : f32 = x / (1f32 + f32.exp (-x))

let swiglu_ffn_forward [seq][d_model][d_ff]
  (hidden: [seq][d_model]f32)
  (up_weight: [d_model][d_ff]f32)
  (gate_weight: [d_model][d_ff]f32)
  (down_weight: [d_ff][d_model]f32)
  (norm_scale: [d_model]f32)
  (norm_bias: [d_model]f32)
  (eps: f32)
  : [seq][d_model]f32 =
  let h_norm = map (\row -> rms_norm row norm_scale norm_bias eps) hidden
  let up = matmul_2d h_norm up_weight
  let gate = matmul_2d h_norm gate_weight
  let act = map2 (\u g -> map2 (\uu gg -> uu * silu gg) u g) up gate
  let down = matmul_2d act down_weight
  map2 (\a b -> map2 (+) a b) hidden down

entry swiglu_forward_entry [seq][d_model][d_ff]
  (hidden: [seq][d_model]f32)
  (up_weight: [d_model][d_ff]f32)
  (gate_weight: [d_model][d_ff]f32)
  (down_weight: [d_ff][d_model]f32)
  (norm_scale: [d_model]f32)
  (norm_bias: [d_model]f32)
  (eps: f32) =
  swiglu_ffn_forward hidden up_weight gate_weight down_weight norm_scale norm_bias eps

entry swiglu_backward_entry [seq][d_model][d_ff]
  (hidden: [seq][d_model]f32)
  (up_weight: [d_model][d_ff]f32)
  (gate_weight: [d_model][d_ff]f32)
  (down_weight: [d_ff][d_model]f32)
  (norm_scale: [d_model]f32)
  (norm_bias: [d_model]f32)
  (eps: f32)
  (grad_out: [seq][d_model]f32)
  : ([seq][d_model]f32,
     [d_model][d_ff]f32,
     [d_model][d_ff]f32,
     [d_ff][d_model]f32,
     [d_model]f32,
     [d_model]f32) =
  vjp (\(h, wu, wg, wd, ns, nb) -> swiglu_ffn_forward h wu wg wd ns nb eps)
      (hidden, up_weight, gate_weight, down_weight, norm_scale, norm_bias)
      grad_out

let softmax_row [n] (x: [n]f32) : [n]f32 =
  let m = reduce f32.max (-1.0/0.0) x
  let ex = map (\v -> f32.exp (v - m)) x
  let s = reduce (+) 0f32 ex
  map (\v -> v / s) ex

let cross_entropy_row [n] (logits: [n]f32) (target: i32) : f32 =
  let p = softmax_row logits
  let t = if target < 0 then 0 else if target >= n then n-1 else target
  let pt = p[t]
  -f32.log (pt + f32_eps)

let lm_head_loss [seq][d_model][vocab]
  (hidden: [seq][d_model]f32)
  (lm_head: [d_model][vocab]f32)
  (targets: [seq]i32)
  : f32 =
  let logits = matmul_2d hidden lm_head
  let losses = map2 (\row t -> cross_entropy_row row t) logits targets
  (reduce (+) 0f32 losses) / f32.i32 seq

entry lm_head_loss_backward [seq][d_model][vocab]
  (hidden: [seq][d_model]f32)
  (lm_head: [d_model][vocab]f32)
  (targets: [seq]i32)
  : (f32, [seq][d_model]f32, [d_model][vocab]f32) =
  let f = \(h, w) -> lm_head_loss h w targets
  let loss = f (hidden, lm_head)
  let (grad_hidden, grad_w) = vjp f (hidden, lm_head) 1f32
  in (loss, grad_hidden, grad_w)

entry embedding_forward [seq][vocab][d_model]
  (tokens: [seq]i32)
  (table: [vocab][d_model]f32)
  : [seq][d_model]f32 =
  map (\t ->
    let ti = if t < 0 then 0 else if t >= vocab then vocab-1 else t
    in table[ti])
  tokens

entry embedding_backward [seq][vocab][d_model]
  (tokens: [seq]i32)
  (grad_hidden: [seq][d_model]f32)
  : [vocab][d_model]f32 =
  let flat_len = vocab * d_model
  let zeros = replicate flat_len 0f32
  let idxs = concat (map2 (\t row ->
      let ti = if t < 0 then 0 else if t >= vocab then vocab-1 else t
      in map (\j -> ti*d_model + j) (iota d_model))
    tokens grad_hidden)
  let vals = concat grad_hidden
  let flat = scatter zeros idxs (+) vals
  in reshape flat : [vocab][d_model]f32

let f32_eps = 1e-8f32

entry clip_grad_norm [n]
  (grads: [n]f32)
  (max_norm: f32)
  : [n]f32 =
  let norm = f32.sqrt (reduce (+) 0f32 (map (\g -> g*g) grads) + f32_eps)
  let scale = if norm > max_norm then max_norm / norm else 1f32
  map (\g -> g * scale) grads

entry lion_step [n]
  (params: [n]f32)
  (m: [n]f32)
  (grads: [n]f32)
  (lr: f32)
  (beta1: f32)
  (beta2: f32)
  (weight_decay: f32)
  : ([n]f32, [n]f32) =
  let m1 = map3 (\mi gi -> mi*beta1 + gi*(1f32-beta1)) m grads
  let upd = map (\x -> if x > 0f32 then 1f32 else if x < 0f32 then -1f32 else 0f32) m1
  let p1 = map2 (\pi ui -> pi - lr*(ui + weight_decay*pi)) params upd
  let m2 = map3 (\mi gi -> mi*beta2 + gi*(1f32-beta2)) m1 grads
  in (p1, m2)

entry muon_step [n]
  (params: [n]f32)
  (m: [n]f32)
  (grads: [n]f32)
  (lr: f32)
  (beta1: f32)
  (beta2: f32)
  (weight_decay: f32)
  : ([n]f32, [n]f32) =
  let m1 = map3 (\mi gi -> mi*beta1 + gi*(1f32-beta1)) m grads
  let v1 = map2 (\gi -> gi*gi) grads
  let denom = map (\x -> 1f32 / f32.sqrt (x + f32_eps)) v1
  let step = map2 (\mi di -> mi*di) m1 denom
  let p1 = map2 (\pi si -> pi - lr*(si + weight_decay*pi)) params step
  let m2 = map3 (\mi gi -> mi*beta2 + gi*(1f32-beta2)) m1 grads
  in (p1, m2)
